#include <stdio.h>
#include <stdlib.h>

#define MAX_N 100005
#define INF 1000000000000000000LL

typedef long long ll;

ll max(ll a, ll b) {
    return a > b ? a : b;
}

int main() {
    int N;
    ll C;
    scanf("%d %lld", &N, &C);

    ll *d = (ll*)malloc((N+1) * sizeof(ll));
    ll *v = (ll*)malloc((N+1) * sizeof(ll));

    for (int i = 1; i <= N; i++) {
        scanf("%lld %lld", &d[i], &v[i]);
    }

    // prefix sums for clockwise direction
    ll *pref_v = (ll*)malloc((N+2) * sizeof(ll));
    ll *pref_d = (ll*)malloc((N+2) * sizeof(ll));
    pref_v[0] = 0;
    pref_d[0] = 0;
    for (int i = 1; i <= N; i++) {
        pref_v[i] = pref_v[i-1] + v[i];
        pref_d[i] = d[i];
    }

    // For counter-clockwise, we consider reversed order
    ll *v_rev = (ll*)malloc((N+2) * sizeof(ll));
    ll *d_rev = (ll*)malloc((N+2) * sizeof(ll));
    for (int i = 1; i <= N; i++) {
        v_rev[i] = v[N - i + 1];
        d_rev[i] = C - d[N - i + 1];
    }

    // prefix for reversed
    ll *pref_v_rev = (ll*)malloc((N+2) * sizeof(ll));
    ll *pref_d_rev = (ll*)malloc((N+2) * sizeof(ll));
    pref_v_rev[0] = 0;
    pref_d_rev[0] = 0;
    for (int i = 1; i <= N; i++) {
        pref_v_rev[i] = pref_v_rev[i-1] + v_rev[i];
        pref_d_rev[i] = d_rev[i];
    }

    // best[i] = max_{1<=j<=i} (pref_v[j] - pref_d[j]) for clockwise
    ll *best_clock = (ll*)malloc((N+2) * sizeof(ll));
    best_clock[0] = -INF;
    for (int i = 1; i <= N; i++) {
        ll val = pref_v[i] - pref_d[i];
        best_clock[i] = max(best_clock[i-1], val);
    }

    // best_rev[i] = max_{1<=j<=i} (pref_v_rev[j] - pref_d_rev[j])
    ll *best_rev = (ll*)malloc((N+2) * sizeof(ll));
    best_rev[0] = -INF;
    for (int i = 1; i <= N; i++) {
        ll val = pref_v_rev[i] - pref_d_rev[i];
        best_rev[i] = max(best_rev[i-1], val);
    }

    ll ans = 0;

    // Case 1: only go clockwise
    for (int i = 1; i <= N; i++) {
        ans = max(ans, pref_v[i] - pref_d[i]);
    }

    // Case 2: only go counter-clockwise
    for (int i = 1; i <= N; i++) {
        ans = max(ans, pref_v_rev[i] - pref_d_rev[i]);
    }

    // Case 3: go clockwise first, then counter-clockwise
    // For each i (clockwise up to i), we can go back counter-clockwise from i
    // Net = pref_v[i] + (pref_v_rev[k] - (pref_d[i] + pref_d_rev[k]))
    // where we subtract the extra distance from i back to start and then to k
    // Actually going clockwise to i, then back to 0 (distance d[i]), then counter-clockwise to some k
    // Total distance = d[i] + pref_d_rev[k]
    // Net nutrition = pref_v[i] + pref_v_rev[k] - d[i] - pref_d_rev[k]
    // = (pref_v[i] - d[i]) + (pref_v_rev[k] - pref_d_rev[k])
    // We need to maximize over i and k
    // Precompute best_rev[k] for k up to N
    for (int i = 1; i <= N; i++) {
        ll base = pref_v[i] - d[i]; // going to i and back to start
        ll best = best_rev[N]; // we can take any k
        ans = max(ans, base + best);
    }

    // Case 4: go counter-clockwise first, then clockwise
    for (int i = 1; i <= N; i++) {
        ll base = pref_v_rev[i] - d_rev[i]; // going to i counter-clockwise and back
        ll best = best_clock[N];
        ans = max(ans, base + best);
    }

    printf("%lld\n", ans);

    free(d);
    free(v);
    free(pref_v);
    free(pref_d);
    free(v_rev);
    free(d_rev);
    free(pref_v_rev);
    free(pref_d_rev);
    free(best_clock);
    free(best_rev);

    return 0;
}

