typedef long long ll;

static ll maxll(ll a, ll b) { return a > b ? a : b; }

int main(void) {
    int N;
    ll C;
    if (scanf("%d %lld", &N, &C) != 2) return 0;

    ll *x = (ll*)malloc((N + 1) * sizeof(ll));
    ll *v = (ll*)malloc((N + 1) * sizeof(ll));
    ll *sum = (ll*)malloc((N + 1) * sizeof(ll));

    for (int i = 1; i <= N; i++) {
        scanf("%lld %lld", &x[i], &v[i]);
    }

    sum[0] = 0;
    for (int i = 1; i <= N; i++) sum[i] = sum[i - 1] + v[i];

    /* best clockwise:
       cw1[i] = max net value by taking some first k<=i sushi clockwise and stopping there
       cw2[i] = max net value by taking some first k<=i sushi clockwise and returning to start
    */
    ll *cw1 = (ll*)malloc((N + 1) * sizeof(ll));
    ll *cw2 = (ll*)malloc((N + 1) * sizeof(ll));
    cw1[0] = 0;
    cw2[0] = 0;
    for (int i = 1; i <= N; i++) {
        ll gain_stop = sum[i] - x[i];
        ll gain_back = sum[i] - 2 * x[i];
        cw1[i] = maxll(cw1[i - 1], gain_stop);
        cw2[i] = maxll(cw2[i - 1], gain_back);
    }

    /* reversed (counterclockwise) arrays */
    ll *rx = (ll*)malloc((N + 1) * sizeof(ll));
    ll *rv = (ll*)malloc((N + 1) * sizeof(ll));
    ll *rsum = (ll*)malloc((N + 1) * sizeof(ll));

    for (int i = 1; i <= N; i++) {
        rx[i] = C - x[N - i + 1];
        rv[i] = v[N - i + 1];
    }

    rsum[0] = 0;
    for (int i = 1; i <= N; i++) rsum[i] = rsum[i - 1] + rv[i];

    ll *ccw1 = (ll*)malloc((N + 1) * sizeof(ll));
    ll *ccw2 = (ll*)malloc((N + 1) * sizeof(ll));
    ccw1[0] = 0;
    ccw2[0] = 0;
    for (int i = 1; i <= N; i++) {
        ll gain_stop = rsum[i] - rx[i];
        ll gain_back = rsum[i] - 2 * rx[i];
        ccw1[i] = maxll(ccw1[i - 1], gain_stop);
        ccw2[i] = maxll(ccw2[i - 1], gain_back);
    }

    ll ans = 0;

    /* Only one direction */
    ans = maxll(ans, cw1[N]);
    ans = maxll(ans, ccw1[N]);

    /* Clockwise first, return, then counterclockwise */
    for (int i = 0; i <= N; i++) {
        ll cur = cw2[i] + ccw1[N - i];
        ans = maxll(ans, cur);
    }

    /* Counterclockwise first, return, then clockwise */
    for (int i = 0; i <= N; i++) {
        ll cur = ccw2[i] + cw1[N - i];
        ans = maxll(ans, cur);
    }

    printf("%lld\n", ans);

    free(x);
    free(v);
    free(sum);
    free(cw1);
    free(cw2);
    free(rx);
    free(rv);
    free(rsum);
    free(ccw1);
    free(ccw2);

    return 0;
}

