        // Prefix sum of nutrition values
        long[] prefix = new long[N + 1];
        for (int i = 0; i < N; i++) {
            prefix[i + 1] = prefix[i] + sushi[i][1];
        }

        // suffix sum (from the end, these are the counterclockwise ones)
        // sum of last j elements = prefix[N] - prefix[N-j]

        long ans = 0;

        for (int i = 0; i <= N; i++) {
            for (int j = 0; j <= N - i; j++) {
                // i sushi clockwise (first i), j sushi counterclockwise (last j)
                long nutrition = prefix[i] + (prefix[N] - prefix[N - j]);

                long cost = 0;
                if (i == 0 && j == 0) {
                    cost = 0;
                } else if (i == 0) {
                    cost = C - sushi[N - j][0];
                } else if (j == 0) {
                    cost = sushi[i - 1][0];
                } else {
                    long cw = sushi[i - 1][0];
                    long ccw = C - sushi[N - j][0];
                    cost = Math.min(2 * cw + ccw, cw + 2 * ccw);
                }

                ans = Math.max(ans, nutrition - cost);
            }
        }

        System.out.println(ans);
    }
