public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        long C = Long.parseLong(st.nextToken());

        long[] dist = new long[N];
        long[] value = new long[N];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            dist[i] = Long.parseLong(st.nextToken());
            value[i] = Long.parseLong(st.nextToken());
        }

        // Prefix sums for clockwise direction
        long[] prefVal = new long[N + 1];
        long[] prefDist = new long[N + 1];
        for (int i = 0; i < N; i++) {
            prefVal[i + 1] = prefVal[i] + value[i];
            prefDist[i + 1] = prefDist[i] + dist[i];
        }
        // We need distances between consecutive points, but we have distances from start.
        // Convert to arc lengths between consecutive points
        long[] arc = new long[N];
        arc[0] = dist[0];
        for (int i = 1; i < N; i++) {
            arc[i] = dist[i] - dist[i - 1];
        }

        // For clockwise: distance to point i from start = dist[i]
        // For counterclockwise: distance to point i from start = C - dist[i]
        // We'll compute best net for clockwise and counterclockwise separately.

        // Clockwise: go from 0 to some point i, possibly with a return to a previous point?
        // Actually we can go clockwise and then turn back counterclockwise to collect more.
        // The optimal strategy: go clockwise to some point i, then go back counterclockwise to some point j < i.
        // Net = sum of values from 0..i + sum of values from j..i-1? Wait careful.
        // Better approach: consider two passes.

        // Let's compute best net for going clockwise only (no backtracking)
        long maxNet = 0;
        long sumVal = 0;
        for (int i = 0; i < N; i++) {
            sumVal += value[i];
            long cost = dist[i];
            long net = sumVal - cost;
            if (net > maxNet) maxNet = net;
        }

        // Counterclockwise only
        sumVal = 0;
        for (int i = N - 1; i >= 0; i--) {
            sumVal += value[i];
            long cost = C - dist[i];
            long net = sumVal - cost;
            if (net > maxNet) maxNet = net;
        }

        // Now consider going clockwise to i, then back counterclockwise to j (j < i)
        // We need to compute best value for each possible turning point.
        // For each i (clockwise endpoint), we need best net from going back to some j.
        // Net = (prefVal[i+1] - prefVal[0]) - dist[i] + (prefVal[i] - prefVal[j]) - (dist[i] - dist[j])
        // Actually better: total value = values from 0..i + values from j..i-1 (exclude i? no, i counted once)
        // Let's define: go clockwise to i, then back counterclockwise to j (j < i). 
        // Path: 0 -> i clockwise, then i -> j counterclockwise.
        // Distance: dist[i] + (dist[i] - dist[j]) = 2*dist[i] - dist[j]
        // Values collected: all from 0 to i (including i) plus all from j to i-1 (since i already counted, j to i-1)
        // So total value = prefVal[i+1] + (prefVal[i] - prefVal[j])
        // Net = prefVal[i+1] + prefVal[i] - prefVal[j] - (2*dist[i] - dist[j])
        // = prefVal[i+1] + prefVal[i] - 2*dist[i] - (prefVal[j] - dist[j])
        // For fixed i, we want to minimize (prefVal[j] - dist[j]) over j < i.

        long[] bestMinus = new long[N + 1];
        bestMinus[0] = Long.MAX_VALUE / 2;
        for (int j = 0; j < N; j++) {
            long val = prefVal[j] - dist[j];
            bestMinus[j + 1] = Math.min(bestMinus[j], val);
        }

        for (int i = 0; i < N; i++) {
            long base = prefVal[i + 1] + prefVal[i] - 2 * dist[i];
            long minPart = bestMinus[i]; // j < i, so use bestMinus[i] (since bestMinus[i] corresponds to j from 0 to i-1)
            long net = base - minPart;
            if (net > maxNet) maxNet = net;
        }

        // Now consider going counterclockwise to i, then back clockwise to j (j > i)
        // Similar logic but mirror.
        // Let's define suffix sums for counterclockwise.
        long[] sufVal = new long[N + 1];
        long[] sufDist = new long[N + 1]; // distance from end (point N-1) going counterclockwise
        for (int i = N - 1; i >= 0; i--) {
            sufVal[i] = sufVal[i + 1] + value[i];
        }
        // Distance from end (point N-1) to point i going counterclockwise = C - dist[i]
        // But for suffix we need distance from i to end? Actually we want to start from 0, go counterclockwise to i, then back clockwise to j.
        // Let's re-index: go counterclockwise from 0 to i (distance = C - dist[i]),
        // then back clockwise from i to j (j > i) distance = dist[j] - dist[i].
        // Total distance = (C - dist[i]) + (dist[j] - dist[i]) = C - 2*dist[i] + dist[j]
        // Values: all from i to N-1 (counterclockwise) plus all from i+1 to j (clockwise)
        // Total value = (sufVal[i]) + (prefVal[j+1] - prefVal[i+1])
        // Net = sufVal[i] + prefVal[j+1] - prefVal[i+1] - (C - 2*dist[i] + dist[j])
        // = sufVal[i] - prefVal[i+1] - C + 2*dist[i] + (prefVal[j+1] - dist[j])
        // For fixed i, maximize (prefVal[j+1] - dist[j]) over j > i.

        long[] bestPlus = new long[N + 2];
        bestPlus[N + 1] = Long.MIN_VALUE / 2;
        for (int j = N - 1; j >= 0; j--) {
            long val = prefVal[j + 1] - dist[j];
            bestPlus[j + 1] = Math.max(bestPlus[j + 2], val);
        }

        for (int i = 0; i < N; i++) {
            long base = sufVal[i] - prefVal[i + 1] - C + 2 * dist[i];
            long maxPart = bestPlus[i + 2]; // j > i, so start from i+1
            long net = base + maxPart;
            if (net > maxNet) maxNet = net;
        }

        System.out.println(maxNet);
    }
}

import java.io.*;
