public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt();
        long C = fs.nextLong();

        long[] x = new long[N + 1];
        long[] v = new long[N + 1];

        for (int i = 1; i <= N; i++) {
            x[i] = fs.nextLong();
            v[i] = fs.nextLong();
        }

        long[] prefix = new long[N + 1];
        for (int i = 1; i <= N; i++) prefix[i] = prefix[i - 1] + v[i];

        // Best value when moving clockwise only, ending at sushi i (no return)
        long[] cwNoReturn = new long[N + 1];
        // Best value when moving clockwise and coming back to start after sushi i
        long[] cwReturn = new long[N + 1];
        // Prefix maxima of above
        long[] bestCwNoReturn = new long[N + 1];
        long[] bestCwReturn = new long[N + 1];

        for (int i = 1; i <= N; i++) {
            cwNoReturn[i] = prefix[i] - x[i];
            cwReturn[i] = prefix[i] - 2L * x[i];
            bestCwNoReturn[i] = Math.max(bestCwNoReturn[i - 1], cwNoReturn[i]);
            bestCwReturn[i] = Math.max(bestCwReturn[i - 1], cwReturn[i]);
        }

        // Counterclockwise arrays from the end
        long[] suffix = new long[N + 2];
        for (int i = N; i >= 1; i--) suffix[i] = suffix[i + 1] + v[i];

        long[] ccwNoReturn = new long[N + 2];
        long[] ccwReturn = new long[N + 2];
        long[] bestCcwNoReturn = new long[N + 2];
        long[] bestCcwReturn = new long[N + 2];

        for (int i = N; i >= 1; i--) {
            long dist = C - x[i];
            ccwNoReturn[i] = suffix[i] - dist;
            ccwReturn[i] = suffix[i] - 2L * dist;
            bestCcwNoReturn[i] = Math.max(bestCcwNoReturn[i + 1], ccwNoReturn[i]);
            bestCcwReturn[i] = Math.max(bestCcwReturn[i + 1], ccwReturn[i]);
        }

        long ans = 0;

        // Only one direction
        ans = Math.max(ans, bestCwNoReturn[N]);
        ans = Math.max(ans, bestCcwNoReturn[1]);

        // Clockwise first, return, then counterclockwise
        for (int i = 0; i <= N; i++) {
            long leftPart = bestCwReturn[i];
            long rightPart = (i + 1 <= N) ? bestCcwNoReturn[i + 1] : 0;
            ans = Math.max(ans, leftPart + rightPart);
        }

        // Counterclockwise first, return, then clockwise
        for (int i = N + 1; i >= 1; i--) {
            long rightPart = bestCcwReturn[i];
            long leftPart = (i - 1 >= 0) ? bestCwNoReturn[i - 1] : 0;
            ans = Math.max(ans, rightPart + leftPart);
        }

        System.out.println(ans);
    }
}

