    for (int i = N - 1; i >= 0; i--) {
        long long nutrition = prefix_val[N] - prefix_val[i];
        long long energy = C - prefix_dist[i];
        ans = max(ans, nutrition - energy);
    }

    // For paths that go clockwise then counterclockwise, or vice versa
    // We need to consider turning points

    // Go clockwise first, then turn back
    // max_val_from_right[i] = max nutrition from going counterclockwise from position i to N-1
    // considering the energy cost to reach the turning point and go back

    vector<long long> max_val_clockwise(N + 1, 0);
    vector<long long> max_val_counter(N + 1, 0);

    // Best value when going clockwise and ending at position i (0-indexed)
    long long best = 0;
    for (int i = 0; i < N; i++) {
        long long curr = prefix_val[i + 1] - prefix_dist[i + 1];
        best = max(best, curr);
        max_val_clockwise[i + 1] = best;
    }

    // Best value when going counterclockwise and ending at position i
    best = 0;
    for (int i = N - 1; i >= 0; i--) {
        long long nutrition = prefix_val[N] - prefix_val[i];
        long long energy = C - prefix_dist[i];
        long long curr = nutrition - energy;
        best = max(best, curr);
        max_val_counter[i] = best;
    }

    // Now consider paths that turn around
    // Go clockwise to i, then back to start, then counterclockwise to j
    for (int i = 0; i < N; i++) {
        long long nutrition_to_i = prefix_val[i + 1];
        long long energy_to_i = prefix_dist[i + 1];
        long long net_to_i = nutrition_to_i - energy_to_i;

        // Now go back to start (another energy_to_i) then counterclockwise
        long long remaining_energy = energy_to_i * 2; // cost to go back

        for (int j = i + 1; j < N; j++) {
            long long nutrition_counter = prefix_val[N] - prefix_val[j];
            long long energy_counter = C - prefix_dist[j];
            long long total_nutrition = nutrition_to_i + nutrition_counter;
            long long total_energy = energy_to_i + remaining_energy + energy_counter;
            ans = max(ans, total_nutrition - total_energy);
        }
    }

    // Go counterclockwise first, then back to start, then clockwise
    for (int j = N - 1; j >= 0; j--) {
        long long nutrition_to_j = prefix_val[N] - prefix_val[j];
        long long energy_to_j = C - prefix_dist[j];
        long long net_to_j = nutrition_to_j - energy_to_j;

        long long remaining_energy = energy_to_j * 2;

        for (int i = 0; i < j; i++) {
            long long nutrition_clockwise = prefix_val[i + 1];
            long long energy_clockwise = prefix_dist[i + 1];
            long long total_nutrition = nutrition_to_j + nutrition_clockwise;
            long long total_energy = energy_to_j + remaining_energy + energy_clockwise;
            ans = max(ans, total_nutrition - total_energy);
        }
    }

    cout << ans << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    int64 C;
    cin >> N >> C;

    vector<int64> x(N + 1), v(N + 1);
    for (int i = 1; i <= N; ++i) cin >> x[i] >> v[i];

    vector<int64> pref(N + 1, 0);
    for (int i = 1; i <= N; ++i) pref[i] = pref[i - 1] + v[i];

    // Best gain going clockwise only, ending at sushi i
    vector<int64> cw1(N + 1, 0), best_cw1(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        cw1[i] = pref[i] - x[i];
        best_cw1[i] = max(best_cw1[i - 1], cw1[i]);
    }

    // Best gain going clockwise and returning to start
    vector<int64> cw2(N + 1, 0), best_cw2(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        cw2[i] = pref[i] - 2 * x[i];
        best_cw2[i] = max(best_cw2[i - 1], cw2[i]);
    }

    // Reverse direction data for counterclockwise handling
    vector<int64> rx(N + 1), rv(N + 1), rpref(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        rx[i] = C - x[N - i + 1];
        rv[i] = v[N - i + 1];
        rpref[i] = rpref[i - 1] + rv[i];
    }

    // Best gain going counterclockwise only
    vector<int64> ccw1(N + 1, 0), best_ccw1(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        ccw1[i] = rpref[i] - rx[i];
        best_ccw1[i] = max(best_ccw1[i - 1], ccw1[i]);
    }

    // Best gain going counterclockwise and returning to start
    vector<int64> ccw2(N + 1, 0), best_ccw2(N + 1, 0);
    for (int i = 1; i <= N; ++i) {
        ccw2[i] = rpref[i] - 2 * rx[i];
        best_ccw2[i] = max(best_ccw2[i - 1], ccw2[i]);
    }

    int64 ans = 0;

    // Only one direction
    ans = max(ans, best_cw1[N]);
    ans = max(ans, best_ccw1[N]);

    // Go clockwise first, return, then go counterclockwise
    for (int i = 0; i <= N; ++i) {
        ans = max(ans, best_cw2[i] + best_ccw1[N - i]);
    }

    // Go counterclockwise first, return, then go clockwise
    for (int i = 0; i <= N; ++i) {
        ans = max(ans, best_ccw2[i] + best_cw1[N - i]);
    }

    cout << ans << '\n';
    return 0;
}
